    public static string Origin(OperationalActionOrigin value) => value switch { OperationalActionOrigin.Manual => "Manual", OperationalActionOrigin.Schedule => "Programação", OperationalActionOrigin.Recovery => "Recuperação", OperationalActionOrigin.Device => "Dispositivo", OperationalActionOrigin.Library => "Biblioteca", _ => "Aplicativo" };
    public static string Type(OperationalEventType value) => value switch
    {
        OperationalEventType.ApplicationStarted => "Aplicativo iniciado", OperationalEventType.ApplicationAutoStarted => "Início com Windows", OperationalEventType.ExitRequested => "Encerramento solicitado", OperationalEventType.ApplicationEnded => "Aplicativo encerrado", OperationalEventType.PreviousSessionUnconfirmed => "Sessão anterior sem confirmação", OperationalEventType.ComputerSuspended => "Computador suspenso", OperationalEventType.ComputerResumed => "Computador retomado",
        OperationalEventType.PlaybackStarted => "Reprodução iniciada", OperationalEventType.PlaybackPaused => "Reprodução pausada", OperationalEventType.PlaybackResumed => "Reprodução retomada", OperationalEventType.PlaybackStopped => "Reprodução parada", OperationalEventType.PlaybackEnded => "Fim da reprodução", OperationalEventType.AutomaticAdvance => "Avanço automático", OperationalEventType.ManualTrackChange => "Troca manual de música", OperationalEventType.PlaybackError => "Erro de reprodução",
        OperationalEventType.RuleActivated => "Regra ativada", OperationalEventType.RuleEnded => "Regra encerrada", OperationalEventType.WinnerChanged => "Mudança de regra", OperationalEventType.AutomaticMode => "Modo Automático", OperationalEventType.ManualMode => "Modo Manual", OperationalEventType.ManualIntervention => "Intervenção manual", OperationalEventType.AutomationSuspended => "Automação suspensa", OperationalEventType.RuleFailed => "Falha de regra",
        OperationalEventType.OutputSelected => "Saída selecionada", OperationalEventType.OutputChanged => "Saída alterada", OperationalEventType.DeviceUnavailable => "Saída indisponível", OperationalEventType.DeviceDisconnected => "Dispositivo desconectado", OperationalEventType.DeviceReconnected => "Dispositivo reconectado", OperationalEventType.DeviceOpenFailed => "Falha de dispositivo", OperationalEventType.RecoveryAttempt => "Tentativa de recuperação", OperationalEventType.RecoverySucceeded => "Recuperação concluída", OperationalEventType.RecoveryExhausted => "Recuperação esgotada",
        OperationalEventType.IndexingStarted => "Indexação iniciada", OperationalEventType.IndexingCompleted => "Indexação concluída", OperationalEventType.LibraryUnavailable => "Pasta indisponível", OperationalEventType.LibraryAccessFailed => "Falha de acesso", OperationalEventType.LibraryReadError => "Erro de leitura", OperationalEventType.LibraryRecovered => "Biblioteca recuperada", OperationalEventType.ImportStarted => "Importação iniciada", OperationalEventType.ImportCompleted => "Importação concluída", OperationalEventType.ImportCancelled => "Importação cancelada", OperationalEventType.ImportFailed => "Falha de importação", _ => "Histórico incompleto"
    };
